    doc2=re.sub(r'§(\d+)\s*'+D+r'\s*§(\d+)(?!\d)(?!\.\d)',' ',doc)
    for m in re.finditer(r'§(\d+)\.(\d+)[a-z]?\s*'+D+r'\s*§?(\d+)(?:\.(\d+))?',doc2):
        a,i,b,j=m.groups()
        if j is None:
            for k in range(int(i),int(b)+1): out.add((int(a),k))
        elif a==b:
            for k in range(int(i),int(j)+1): out.add((int(a),k))
        else: out.add((int(a),int(i))); out.add((int(b),int(j)))
    for m in re.finditer(r'§(\d+)(?:\s*,\s*|\s*\(\s*)items?\s+(\d+)(?:\s*'+D+r'\s*(\d+))?',doc2):
        a,i,j=int(m.group(1)),int(m.group(2)),m.group(3)
        for k in range(i,(int(j) if j else i)+1): out.add((a,k))
    for m in re.finditer(r'§(\d+)\.(\d+)',doc2): out.add((int(m.group(1)),int(m.group(2))))
    for m in re.finditer(r'§(\d+)\s+¶(\d+)(?:\s*'+D+r'\s*¶?(\d+))?',doc2):
        a,i,j=int(m.group(1)),int(m.group(2)),m.group(3)
        for k in range(i,(int(j) if j else i)+1): out.add((a,'¶%d'%k))
    for m in re.finditer(r'§(\d+)(?!\d)(?!\.\d)',doc2): out.add((int(m.group(1)),None))
    return out,weak
idx=collections.defaultdict(list)
