    c,w=cites2(r['doc'])
    short=r['name'].replace('Ern.MemoryModel.','').replace('Ern.Lib.','Lib.')
    mod=r['file'].replace('Ern/','').replace('.lean','')
    for k in c|w: idx[k].append((mod,short,r['kind']))
